package com.stockshield.service; import com.stockshield.dto.CreateProductRequest; import com.stockshield.entity.Product; import com.stockshield.repository.ProductRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ProductService {private final ProductRepository repo; public ProductService(ProductRepository r){repo=r;} @Transactional public Product create(CreateProductRequest r){Product p=new Product();p.setSku(r.sku());p.setName(r.name());p.setInventory(r.inventory());p.setInitialInventory(r.inventory());return repo.save(p);} public List<Product> all(){return repo.findAll();} @Transactional public Product reset(Long id,int qty){Product p=repo.findLockedById(id).orElseThrow();p.setInventory(qty);p.setInitialInventory(qty);return p;}}
